SELECT 'TFILE' AS SRC, COUNT(*) AS N_ROWS, SUM(CASE WHEN RDXSRCT_CODE IS NULL OR TRIM(CAST(RDXSRCT_CODE AS STRING)) = '' OR LOWER(TRIM(CAST(RDXSRCT_CODE AS STRING))) = 'null' THEN 1 ELSE 0 END) AS BAD_RDXSRCT_CODE, SUM(CASE WHEN RDXSET_ID IS NULL OR TRIM(CAST(RDXSET_ID AS STRING)) = '' OR LOWER(TRIM(CAST(RDXSET_ID AS STRING))) = 'null' THEN 1 ELSE 0 END) AS BAD_RDXSET_ID, 0 AS BAD_RDXSRCR_CODE
FROM `${hivevar:environment}_PERSIST_RDXSRC_DB`.RDXSRC_TBL_RDXSRC_RDXSET_TFILE_INFO WHERE DL_DATA_DT = '${hivevar:dl_data_dt}'
UNION ALL
SELECT 'RFILE' AS SRC, COUNT(*) AS N_ROWS, SUM(CASE WHEN RDXSRCT_CODE IS NULL OR TRIM(CAST(RDXSRCT_CODE AS STRING)) = '' OR LOWER(TRIM(CAST(RDXSRCT_CODE AS STRING))) = 'null' THEN 1 ELSE 0 END) AS BAD_RDXSRCT_CODE, 0 AS BAD_RDXSET_ID, SUM(CASE WHEN RDXSRCR_CODE IS NULL OR TRIM(CAST(RDXSRCR_CODE AS STRING)) = '' OR LOWER(TRIM(CAST(RDXSRCR_CODE AS STRING))) = 'null' THEN 1 ELSE 0 END) AS BAD_RDXSRCR_CODE
FROM `${hivevar:environment}_PERSIST_RDXSRC_DB`.RDXSRC_TBL_RDXSRC_RDXSET_RFILE_INFO WHERE DL_DATA_DT = '${hivevar:dl_data_dt}';
